<template><div class="chat-history-panel"><div class="modal-heading"><h3>Conversation history</h3><IconButton icon="cancel" label="Close history" @click="$emit('close')"/></div><div v-if="loading" class="state-message">Loading history…</div><div v-else class="chat-history-list"><div v-for="c in rows" :key="c.id" class="chat-history-row"><span class="chat-history-label"><b>{{c.title}}</b><small>{{new Date(c.updated_at).toLocaleString()}}</small></span><IconButton icon="view" label="Open conversation" @click="$emit('open',c.id)"/><IconButton icon="delete" label="Delete conversation" variant="danger" @click="remove(c.id)"/></div></div><ConfirmDialog :open="!!pendingDelete" title="Delete conversation" message="Delete this conversation and its saved messages?" confirm-label="Delete conversation" danger @cancel="pendingDelete=null" @confirm="confirmRemove"/></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import api from'@/services/api';import IconButton from'@/components/ui/IconButton.vue';import ConfirmDialog from'@/components/ui/ConfirmDialog.vue';const emit=defineEmits<{close:[];open:[id:string]}>();const rows=ref<any[]>([]),loading=ref(false),pendingDelete=ref<string|null>(null);async function load(){loading.value=true;try{rows.value=(await api.get('/v1/chat/conversations')).data}finally{loading.value=false}}function remove(id:string){pendingDelete.value=id}async function confirmRemove(){if(!pendingDelete.value)return;await api.delete(`/v1/chat/conversations/${pendingDelete.value}`);pendingDelete.value=null;await load()}onMounted(load);</script>
